def prod_signs(arr):
    if not arr:
        return None
    product_of_signs = 1
    sum_of_magnitudes = 0
    for num in arr:
        if num == 0:
            return 0
        product_of_signs *= (-1) ** num
        sum_of_magnitudes += abs(num)
    return sum_of_magnitudes * product_of_signs

def is_nested(string):
