        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if stack:
                    return True
    return False

def largest_smallest_integers(lst):
    negative_integers = [x for x in lst if x < 0]
    positive_integers = [x for x in lst if x > 0]

    if not negative_integers:
        a = None
    else:
        a = max(negative_integers)

    if not positive_integers:
        b = None
    else:
        b = min(positive_integers)

    return (a, b)

def fix_spaces(text):
    result = []
    space_count = 0
    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 2:
                result.append('-')
            elif space_count > 0:
                result.append('_')
            space_count = 0
            result.append(char)
    if space_count > 2:
        result.append('-')
    elif space_count > 0:
        result.append('_')
    return ''.join(result)

def bf(planet1, planet2):
    solar_system = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in solar_system or planet2 not in solar_system:
        return ()
    index1 = solar_system.index(planet1)
    index2 = solar_system.index(planet2)
    if index1 > index2:
        index1, index2 = index2, index1
    return solar_system[index1 + 1:index2]

